// WERE-KIN (rust). The FINAL 12 animal kinds x 3 lodges = 36 characters; 7 support.
// Kinds: Wolf, Raccoon, Crocodile, Capybara, Axolotl, Raven, Owl, Octopus, Mantis Shrimp, Moth, Pangolin, Spider.
GROUP_DEFS.were = {
  id: "were", name: "Were-Creature", icon: "wolf", color: PEOPLE_COLORS.were.color, color2: PEOPLE_COLORS.were.color2,
  levelNames: ["Animal Kind", "Lodge"],
  tagline: "Two hearts, one war-band.",
  summary: "People who share their skin with an animal: wolf, raccoon, crocodile, octopus, moth and more. In person form they look like hard, weathered survivors with one telling trait. In beast form they are real animals, scaled up and carrying the scars of every fight. The Kin are the Dim's most varied fighters and its most loyal friends.",
  lore: "The Kin call themselves a Den, one family under many hides. Twelve animal-kinds hold seats at the Moot, a war council held on the first full moon of every season where treaties are signed in blood-and-oil and grudges are settled by sparring. Their ancient enemy is the Static, a creeping silence that eats color and sound from wild places.",
  traits: { Power: 4, Resilience: 4, Mystery: 3, Social: 3, Versatility: 5 },
  playstyle: "Pick an Animal Kind and a Lodge, then a Breed and a Moon Role. Shift between forms mid-fight and manage the Rage meter. Pack bonuses reward fighting together.",
  extras: [
    {
      title: "How Were-kin work",
      items: [
        { name: "Breeds", desc: "Hearth-born (raised human, learned the truth later), Wild-born (born animal, learned to walk upright) and Between-born (both parents Kin, always a little feral). Breed sets which form you favor." },
        { name: "Moon Roles", desc: "New Moon Imp (scout and saboteur), Crescent Seer (spirit-talker), Half-Moon Judge (arbiter), Gibbous Bard (storyteller) and Full Moon Guardian (warrior). A Moon Role is independent of animal kind." },
        { name: "Five forms", desc: "Person, Peekaboo (ears, tail or claws slip out), Big Fluff (the upright war form), Beast (full animal) and Pocket (tiny scouting form). Aquatic kinds add a Tide form: fully amphibious, slick and fast in water." },
        { name: "Rage", desc: "Hits, insults and silver fill the Rage meter. Low Rage sharpens focus and damage. At full Rage you go Berserk: powerful, loud and not listening." },
        { name: "Weaknesses", desc: "Silver burns. The Static saps color and strength. Most Kin cannot keep a secret about snacks." },
      ],
    },
  ],
  subs: [
    /* 1 ------------------------------------------------ CANINE-KIN */
    M("canine", "Canine-kin", "wolf", "The pack is the point.",
      "Three kinds of canine, three roles: the Bone-Crusher (a bear-sized juggernaut), the Torrent Strider (a river skirmisher) and the Wool Dog Dream-Weaver (a spirit tactician). Werewolves with the Pack's loyalty and very different jobs.",
      "The Pack runs on kin-bonds, and the Canine-kin carry them in three forms: the war-hound that cracks armor, the river-hound that drowns the land and the wool-dog that weaves a ward. Every form answers to the Alpha.",
      [
        L("bonecrushers", "Bone-Crusher Juggernauts", "wolf", "combat", "Armor is just a shell.",
          "Bear-sized werewolves with a brutal jaw, based on Epicyon. Bone-Crushers shatter armor, break weapons and feed on the marrow of what they crack.",
          "The old war-hounds had jaws built for bone, not chase. A Bone-Crusher walks into a shield wall and leaves with the shields.",
          ["Ignores part of enemy armor, breaks shields", "Heals by biting armored or large foes"], ["Slow to turn", "Poor against fast skirmishers"],
          ["Shatter: bite through armor and break a weapon", "Marrow Feast: bite a big foe to heal on its marrow", "Jaw Lock: pin a target in place"],
          "Armored collar, bone-crusher jaw guard, studded shoulder plates, marrow flask",
          "Huge, bear-sized wolf-kin with a short brutal jaw and a thick neck, armor plates on the shoulders, jaws open on a cracked shield.", ["#8f6e3d", "#f4f1e8", "#ff5d8f"]),
        L("torrentstriders", "Bush Dog Torrent Striders", "waves", "combat", "The river takes what the pack leaves.",
          "Low, sleek bush-dog werewolves with webbed paws and a rudder tail. Torrent Striders vanish in water and mud and drag prey under.",
          "Bush dogs hunt in the river and the pack hunts with them. A Strider is gone when the water closes and back when something screams.",
          ["Invisible and very fast in water or mud", "Drowning debuff drains the stamina of land targets"], ["Weak and slow in dry places", "Fragile when exposed"],
          ["Aquatic Mastery: huge speed and invisibility submerged", "Pack Drag: a drowning grab that saps stamina", "Rudder Sweep: a tail strike that trips"],
          "Webbed gauntlets, rudder-tail harness, river-skin cloak, glowing paw bands",
          "Low, sleek otter-like were-hound with a broad rudder tail and glowing webbed paws, half submerged and grinning.", ["#31a6c4", "#1f2438", "#ff8a3d"]),
        L("caninedreamweavers", "Wool Dog Dream-Weavers", "flower", "support", "Spin a ward. Keep them warm.",
          "Majestic white wool-dog werewolves who shed spirit wool: glowing barriers for allies and sticky silk for enemies.",
          "The Salish wool dogs were shorn for blankets and wove the first wards. A Dream-Weaver sheds the wool, weaves the veil and lets the Pack sleep.",
          ["Barriers for allies, snares for enemies", "Raises evasion and magic resistance for the party"], ["Low damage", "Wool can be burned"],
          ["Ward-Wool: shed glowing wool as a shield or a snare", "Ceremonial Veil: a shroud that boosts evasion and magic resistance", "Dream Weave: lull a target into slow sleep"],
          "Wool-spindle staff, ceremonial veil, woven sash, glowing wool tufts",
          "Majestic pure-white cloud-furred wool-dog with a woven ceremonial veil, glowing wool drifting from a spindle staff.", ["#c3c0ed", "#e8c76a", "#06d6a0"]),
      ]),
    /* 2 ------------------------------------------------ ARCTOIDEA-KIN */
    M("arctoidea", "Arctoidea-kin", "bear", "Little hands. Big ideas.",
      "Seven mammals of the bear-raccoon-seal-weasel side of the carnivore family: the raccoon, the red panda, the short-faced bear, the swan-necked seal, the honey badger, the sea otter and the stink badger.",
      "Raccoons, pandas, bears, seals and badgers share a family tree and an aversion to staying where they are told. They fight with hands, hides and very particular smells.",
      [
        L("maskbandits", "Raccoon Mask Bandits", "mailbox", "combat", "A locked door is a challenge.",
          "Masked raiders who crack vaults, lift convoys and vanish before the alarm. Mask Bandits fight with quick blades, smoke and nimble hands.",
          "They wear a stripe of black across the eyes, and every Bandit's stripe is cut from a different stolen tape.",
          ["Superb lockpicking and stealth", "Steal gear mid-fight"], ["Fragile in a stand-up fight", "Greedy, which gets them caught"],
          ["Sticky Fingers: steal an item or buff", "Smoke Bomb: vanish and reposition", "Crowbar Crack: burst open a lock or a guard"],
          "Crowbar, smoke bombs, lockpick roll, striped mask",
          "Masked raccoon-kin in a patched trench coat crouched over a cracked safe, crowbar in hand, ringed tail curled.", ["#dea013", "#7d99ca", "#282956"]),
        L("redpandamonks", "Red Panda Bamboo Monks", "leaf", "support", "Tea first. Then healing.",
          "Red panda monks who brew bamboo tea that mends the wounded and calms a fight. Bamboo Monks meditate in the canopy and heal from above.",
          "The red pandas kept the oldest tea in the Overgrowth. A Monk pours a cup, and the party remembers what peace tastes like.",
          ["Strong team healing and calming", "Safe in trees and high ground"], ["Low offense", "Clumsy on open ground"],
          ["Bamboo Brew: heal and calm an area", "Tail Wrap: a warm tail-shield that guards an ally", "Canopy Perch: gain height and heal from above"],
          "Bamboo staff, tea kettle, striped tail, monk's sash",
          "Round red panda monk with a ringed tail, a bamboo staff and a steaming kettle.", ["#cd521d", "#f4f1e8", "#ff5d8f"]),
        L("shortfacedbear", "Short-Faced Bear Gallopers", "bear", "combat", "Run it down.",
          "Ice Age giants on long slender legs. Gallopers charge at horse speed and an intimidating aura cows everything near them.",
          "The short-faced bears outran everything and ate what they caught. A Galloper never walks into a fight; it arrives.",
          ["Charges at horse speed with no heavy penalty", "Huge health and an intimidation aura"], ["Slow to turn", "Dangerous to its own allies when charging"],
          ["Terrifying Gallop: charge and knock down targets", "Apex Vigor: a huge health pool", "Intimidation Aura: lowers the attack of nearby enemies"],
          "Tall spiked collar, charge harness, long leg wraps, trophy bones",
          "Gaunt, long-legged bear-kin charging forward, a short deep snout and a spiked collar, wraps on every leg.", ["#5a452b", "#1f2438", "#ff8a3d"]),
        L("sealcoilstrikers", "Swan-Neck Seal Coil-Strikers", "waves", "combat", "Reach farther. Strike faster.",
          "Sleek seals with a long swan-like neck that whips out to snap at prey. Coil-Strikers hit from behind the front line and counter in water.",
          "Acrophoca had a neck like a swan and a jaw like a trap. A Coil-Striker coils, waits and is suddenly at your throat.",
          ["Double melee reach, strikes around shields", "Auto-counters while dodging in water"], ["Weak on land", "Fragile body"],
          ["Serpentine Strike: a whip-neck bite with double reach", "Pelagic Coil: dodging in water triggers a counter", "Slick Slide: glide along wet ground"],
          "Neck guard, coil harness, piercing tooth bracers, wet cloak",
          "Sleek seal-kin with a long flexible neck coiled like an S, ready to whip out.", ["#2938c2", "#e8c76a", "#06d6a0"]),
        L("honeybadgers", "Honey Badger Loose-Hides", "shield", "combat", "Grab me. See what happens.",
          "Fearless badgers with loose hides that spin inside their own skin, immune to grapples and poison.",
          "The honey badger has a hide that rotates and a temper that doesn't. A Loose-Hide takes a bite, turns in its skin and takes the biter's face.",
          ["Immune to grapples, pins and binds", "Poison fills a rage meter instead of hurting"], ["Low defense against big hits", "Reckless"],
          ["Loose-Hide Evasion: ignore grapples and pins", "Mithridatism: poison and acid fuel Rage", "Spin-Back: twist in the hide to hit a grabber"],
          "Patched leather vest, spiked knuckles, white back-stripe cape, venom-proof gloves",
          "Compact honey-badger-kin with a white back stripe, spiked knuckles and a grin, turning in its own loose hide.", ["#bab7ab", "#2d2a4a", "#4cc9f0"]),
        L("seaotters", "Sea Otter Anvil-Smashers", "otter", "combat", "Crack it open.",
          "Sea otters who carry an anvil rock in a skin pouch and smash it over enemy heads. Cold-proof and launching out of water like rockets.",
          "The sea otter is the only sea mammal with a favorite tool. An Anvil-Smasher keeps a good rock for every occasion.",
          ["Smashes with environmental objects", "Immune to cold, launches out of water"], ["Needs a rock", "Light armor"],
          ["Anvil Pocket: equip a rock or ruin to smash", "Insulating Buoyancy: ignore cold and launch from water", "Chest Crack: a heavy two-handed smash"],
          "Anvil rock pouch, thick fur collar, shell-crusher mallet, kelp belt",
          "Round sea-otter-kin floating on its back-hop pose with an anvil rock raised overhead.", ["#b09a3b", "#fff7e0", "#c77dff"]),
        L("stinkbadgers", "Stink Badger Possum-Gassers", "cloud-fog", "combat", "Play dead. Then it gets worse.",
          "Stink badgers who fake death and then flood the area with sulfur gas. Possum-Gassers wipe aggro, then blind and confuse everyone.",
          "The Sunda stink badger lets the predator come close. The predator regrets it. So does everyone within thirty feet.",
          ["Fakes death to drop all aggro", "Confuses enemies into attacking each other"], ["Weak in a stand-up fight", "Gas hurts allies too"],
          ["Playing Possum: drop all aggro by faking death", "Miasmatic Nausea: a gas cloud that disorients", "Sulfur Burst: a short-range blinding spray"],
          "Gas mask, spray canisters, striped back cape, ash-grey wraps",
          "Skunk-like stink-badger-kin in a gas mask lying limp, a sulfur cloud rising.", ["#a9bc2f", "#26324a", "#ffd23f"]),
      ]),
    /* 3 ------------------------------------------------ CROCODYLIA-KIN */
    M("crocodylia", "Crocodylia-kin", "alligator", "Armor with an appetite.",
      "Six crocodilians across three families: the Purussaurus (a colossus), the dwarf caiman (a bone-plate scout), the Cuban crocodile (a galloper), the Armadillosuchus (a burrower), the gharial (a sonic duelist) and the Herugavialis (a coast strider).",
      "Crocodilians are the oldest armor on the river. The Pack's cousins took the shapes of giants and scouts, gallopers and burrowers, and a few fish-snapping needle-snouts.",
      [
        L("purussaurus", "Purussaurus Death-Rollers", "alligator", "combat", "One bite. One roll.",
          "Colossal caimans from the Miocene. Death-Rollers grab, twist and tear apart the biggest bosses.",
          "Forty feet of broad blunt skull and twisting jaw. A Death-Roller takes the thing that thought it was the largest.",
          ["Massive damage and size", "Death Roll tears a target apart"], ["Slow and huge", "Easy to surround"],
          ["Death Roll: grab and twist for huge damage", "Colossus Bite: crush armor", "Mud Wallow: regenerate in wet ground"],
          "Skull-guard helm, tail spike, trophy chains, scute plates",
          "Colossal blunt-snouted caiman-kin with a huge broad skull and a tail weighted with chains.", ["#1d721f", "#f4f1e8", "#ff5d8f"]),
        L("caimanscouts", "Dwarf Caiman Bone-Plate Scouts", "shield", "combat", "Small. Hard. Everywhere.",
          "Tiny, bone-plated dwarf caimans who scout rough ground inside armor so rigid nothing can bite through.",
          "Even their bellies are armored. A Scout can lie in a ditch all day and nothing gets past the plates.",
          ["Very high defense for a small frame", "Excellent on land"], ["Stiff and slow to turn", "Low damage"],
          ["Bone-Plate Armor: take less damage from every side", "Ditch Watch: scout from cover and spot ambushes", "Shell Rush: a shield-bash charge"],
          "Bone-plate vest, domed helm, scout satchel, short spear",
          "Small dwarf caiman-kin covered in bony plates with a high domed skull and a short spear.", ["#238b2d", "#1f2438", "#ff8a3d"]),
        L("cubancrocodiles", "Cuban Crocodile Gallop Vanguard", "alligator", "combat", "They run on land.",
          "Fast, athletic crocodiles that gallop on long legs and leap clear of the water to snap at anything on a branch.",
          "The Cuban crocodile is the most land-minded of its family. A Vanguard hits the ground running and doesn't stop for a fence.",
          ["Gallops at high speed on land", "Leaping bite from the water"], ["Light armor", "Burns out quickly"],
          ["Gallop: charge at high speed", "Leap Snap: launch out of the water for a bite", "Turtle Crusher: flat molars crack shells"],
          "Running harness, leg straps, tooth guard, light scute vest",
          "Lean long-legged crocodile-kin galloping, jaws wide, a spiked tail trailing.", ["#6eb83d", "#e8c76a", "#06d6a0"]),
        L("armadillosuchus", "Armadillosuchus Burrow-Juggernauts", "pickaxe", "combat", "From below.",
          "Armored, armadillo-shelled croc-kin that dig underneath and rise behind the line. Segmented plates cut flank damage.",
          "It gave up the water for the dirt. A Burrow-Juggernaut sinks into the floor and appears behind the shield wall.",
          ["Burrows to ambush from below", "Segmented armor reduces flank damage"], ["Slow on the surface", "Weak to flooding"],
          ["Burrow: dig under and strike from below", "Segmented Shell: take less damage from the back and sides", "Digging Claws: tear up cover"],
          "Jointed shell plates, digging claws, tunnel lamp, dirt-caked cloak",
          "Armored crocodile-kin with an armadillo-like jointed shell and heavy curved digging claws.", ["#ab8349", "#2d2a4a", "#4cc9f0"]),
        L("gharialduelists", "Gharial Sonic Duelists", "music", "combat", "Buzz. Pop. Pierce.",
          "Needle-snouted gharials with a bulbous ghara that buzzes and stuns. Sonic Duelists pierce fast and fill the water with shock.",
          "Males grow a hollow knob on the snout that hums like an instrument. A Duelist plays it before the first stab.",
          ["Fast piercing strikes", "Sonic pulse stuns groups"], ["Weak crushing power", "Fragile jaw"],
          ["Ghara Buzz: a sonic pulse that stuns", "Needle Snap: a high-precision piercing strike", "Bubble Curtain: a stunning wall of bubbles"],
          "Ghara resonator, needle-snout guard, fin sash, shock bracers",
          "Slender gharial-kin with a needle-thin snout and a bulbous ghara, sonic rings rippling out.", ["#43d0cb", "#fff7e0", "#c77dff"]),
        L("herugavialis", "Herugavialis Tidal Marauders", "waves", "combat", "The sea is ours.",
          "Saltwater gavials from the ancient Tethys coast. Tidal Marauders gain big bonuses in deep sea and heavy currents.",
          "Found in the rock cut for the Sphinx, a gavial that gave up the calm river for the open sea. A Marauder swims into the surf and everyone else drowns.",
          ["Strong bonuses at sea and in currents", "Fast swimmer with a piercing bite"], ["Weak inland", "Needs water"],
          ["Tidal Rush: a fast surf charge", "Current Rider: bonus damage in currents", "Sea Fang: a piercing bite that stuns"],
          "Surf cloak, salt-iron harness, wave-fang spear, kelp wraps",
          "Sleek saltwater gavial-kin with a long snout riding a wave, a trident-like spear in one hand.", ["#6992d3", "#26324a", "#ffd23f"]),
      ]),
    /* 4 ------------------------------------------------ RODENT-KIN */
    M("rodent", "Rodent-kin", "capybara", "Be calm. Be everywhere.",
      "Six rodents: the capybara healer, the giant Josephoartigasia, the poison-wick crested rat, the Castoroides beaver, the naked mole-rat swarm and the giant flying squirrel.",
      "Rodent-kin are the most numerous of the Pack's cousins: from the quiet capybaras on the springs to prehistoric giants and the pain-proof mole-rat colonies underground.",
      [
        L("hotspringhealers", "Rodent Hot-Spring Healers", "waves", "support", "Soak. Heal. Forgive.",
          "Medics who run the communal hot-springs. Hot-Spring Healers restore the wounded, calm tempers and keep even the grumpiest veterans at peace.",
          "Every spring is neutral ground. A Healer's rule: nobody fights in the water, and nobody leaves angry.",
          ["Strong healing over time and calming auras", "Safe-zone creation"], ["Almost no offense", "Slow to move"],
          ["Warm Soak: heal and calm an area", "Steam Veil: block line of sight", "Bath House: create a safe zone"],
          "Steam kettle, herb bundle, ribbon sash, spring-water vials, a crystal-wearing raccoon companion",
          "Tall, soft capybara-kin in a mint-and-pink ribbon robe with flowers in her hair, pouring steam from a kettle with one hand, herbs in the crook of the other arm, a small raccoon assistant at her feet wearing a belt of glowing crystals.", ["#bcfec8", "#ffadad", "#c9c588"]),
        L("joseptusks", "Josephoartigasia Tusk-Breakers", "shield", "combat", "Tusks first.",
          "The largest rodent ever, a two-thousand-pound Pliocene giant with tusk-like incisors. Tusk-Breakers smash shields and armor head on.",
          "It had a skull the size of a bull's and incisors that worked like tusks. A Tusk-Breaker uses them like a ram.",
          ["Breaks armor and shields", "Huge health and bite force"], ["Slow turn", "Large target"],
          ["Tusk Charge: smash a shield or armor", "Incisor Gouge: pry open a defense", "Mega-Fauna Stomp: a ground shock"],
          "Tusk caps, ram collar, hide plates, stomp boots",
          "Huge, bull-skulled rodent-kin with two long tusk-like incisors capped in iron and a thick hide.", ["#ca7649", "#f4f1e8", "#ff5d8f"]),
        L("crestedratwardens", "African Crested Rat Poison-Wick Wardens", "flower", "combat", "Touch me. See what happens.",
          "Crested rats that gnaw poison bark and wear it in wick-like hairs. Poison-Wick Wardens are armored tanks that punish every hit with poison.",
          "It steals lethal bark and wears it along its flanks. When it parts its fur, the warning stripes show. The next bite is the last.",
          ["Retaliatory poison on every hit", "Parts its fur for a warning-stripe stance"], ["Slow to attack", "Poison needs a few turns to prime"],
          ["Poison Wick: attackers take poison damage", "Warning Stripe: part the fur to enter a retaliation stance", "Bark Gnaw: restock the poison"],
          "Poison-wick cloak, bark satchel, warning-stripe mantle, thorn guard",
          "Crested rat-kin with a spiky crest and a black-and-white striped flank parted to show the warning pattern.", ["#ae2fbc", "#1f2438", "#ff8a3d"]),
        L("castoroides", "Castoroides Wetland Overlords", "waves", "combat", "The marsh obeys.",
          "Bear-sized giant beavers with blunt incisors and huge paddle tails. Wetland Overlords flood the field and sweep crowds away.",
          "It never cut trees or built dams. It ruled the swamp. An Overlord pushes the swamp where it wants it.",
          ["Controls water and terrain", "Massive tail sweeps for crowd control"], ["Slow on dry land", "Large target"],
          ["Tail Sweep: a huge crowd-control paddle", "Flood Field: turn an area to marsh", "Deep Dive: stay underwater for a long ambush"],
          "Paddle-tail guard, marsh cloak, blunt-incisor bracer, reed belt",
          "Bear-sized giant beaver-kin with a huge flat paddle tail raised for a sweep.", ["#2b644b", "#e8c76a", "#06d6a0"]),
        L("molematehive", "Naked Mole-Rat Hive-Colonists", "egg", "combat", "Pain is for other people.",
          "Pink, pain-proof mole-rats that fight as a colony. Hive-Colonists ignore status effects and split into duplicates that soak hits.",
          "The queen decides. The workers dig. The soldiers feel nothing. A Colonist is all three.",
          ["Immune to bleed, stun and chemical damage", "Colony duplicates absorb hits"], ["Weak alone", "Squishy"],
          ["Substance None: ignore pain and status effects", "Colony Call: summon duplicates to absorb threats", "Queen's Order: boost the swarm"],
          "Digging gauntlets, tunnel lamp, queen's sigil sash, soldier helm",
          "Pink wrinkled mole-rat-kin with big front teeth and a digging gauntlet, small duplicates in a tunnel behind.", ["#e0aece", "#2d2a4a", "#4cc9f0"]),
        L("flyingsquirrels", "Giant Flying Squirrel Glide-Strikers", "squirrel", "combat", "Drop. Hit. Gone.",
          "Large gliders with a skin membrane and a rudder tail. Glide-Strikers dive on targets from height and zip away on vertical surfaces.",
          "They fall like a thrown cloak and land like a punch. A Glide-Striker is already off the wall before the echo.",
          ["Converts height into dive-bomb damage", "Fast mobility along walls"], ["Fragile", "Needs high ground"],
          ["Patagium Glide: glide long distances", "Dive Bomb: a momentum strike from above", "Wall Zip: leap along vertical surfaces"],
          "Membrane cape, glide harness, talon gloves, goggles",
          "Giant flying squirrel-kin gliding with a wide skin membrane between the arms and legs, a rudder tail steering.", ["#5729c2", "#fff7e0", "#c77dff"]),
      ]),
    /* 5 ------------------------------------------------ SALAMANDER */
    M("salamander", "Salamander-kin", "axolotl", "Smile. Regrow. Strike.",
      "Five amphibians, five superpowers: the axolotl (endless regeneration), the giant salamander (a vacuum bite), the olm (a century of patience), the ribbed newt (bones as weapons) and the hellbender (breathing through its skin).",
      "They live in flooded basements, sunken vaults, blind caves and cold fast rivers. Lose a limb and a salamander grows it back, which is why they fight like they have nothing to lose.",
      [
        L("regrowthmedics", "Axolotl Regrowth Medics", "medic", "support", "We can regrow that.",
          "Axolotl field medics who regenerate wounded allies. Regrowth Medics knit flesh, reattach armor and bring the fallen back on their feet.",
          "A Medic's own gills glow when they heal, and the whole camp knows someone is being saved.",
          ["Strongest regeneration and revive in the game", "Cleanse wounds and status effects"], ["Fragile", "Low offense"],
          ["Regrowth: heal over time and restore armor", "Gill Glow: reveal hidden injuries", "Second Wind: revive a fallen ally"],
          "Med satchel, glow-gel flask, bandage reel, field lamp",
          "Smiling axolotl-kin with glowing pink gills holding a med satchel, healing light spilling from one hand.", ["#f790c3", "#4cc9f0", "#fff0d1"]),
        L("mawwardens", "Giant Salamander Maw Wardens", "alligator", "combat", "Open wide. Say nothing.",
          "Giant salamanders the size of a door who lie motionless on dark riverbeds and snap shut with a vacuum bite. Maw Wardens guard the river crossings and swallow what tries to pass.",
          "The largest living amphibians sit so still that boats float over them. A Maw Warden feels every footstep in the water long before it arrives.",
          ["Huge size and heavy damage", "Vacuum bite pulls targets in"], ["Slow to turn", "Weak out of water"],
          ["Vacuum Bite: pull a target in and crush it", "Still Water: sense every vibration nearby", "Riverbed Slam: knock down everything in front"],
          "Riverbed hammer, sensor-node collar, wide-mouth helm, river-stone plating",
          "Huge, wide-mouthed giant salamander with a flat head and tiny eyes rising from the water, jaws agape, bone-plated shoulders streaming.", ["#5a6b5e", "#e8c76a", "#c94b3a"]),
        L("olmseers", "Olm Dark-Cave Seers", "eye", "combat", "I have time. You do not.",
          "Blind, pale cave-dwellers who live for a century and can go ten years without a meal. Dark-Cave Seers feel the world through vibration and strike with ancient patience.",
          "They sit in flooded caves where nothing has changed in a thousand years, and they have outwaited every army that came looking.",
          ["Senses everything through vibration", "Extreme endurance: never hungry, hard to wear down"], ["Blind in the open air", "Slow to act"],
          ["Still Sense: reveal every moving enemy nearby", "Long Fast: reduce damage while stationary", "Cave Whisper: a vibration spell that stuns"],
          "Cave-stick, vibration drum, pale cloak, fast-bead string",
          "Pale, eyeless olm-kin with a long thin body and red external gills holding a cave-stick, one hand to the ground feeling for footsteps.", ["#d9c3b8", "#7a3a5a", "#4cc9f0"]),
        L("boneskirmishers", "Ribbed Newt Bone-Skirmishers", "bone", "combat", "Sharp where it counts.",
          "Newt skirmishers who push their own sharp ribs through their skin, tipped with poison. Bone-Skirmishers fight in close, bursting into a ring of venomous spikes when cornered.",
          "The tips of the ribs pass through poison glands on the way out. It hurts them too. They say that is the point.",
          ["Poison rib burst when hit", "Strong close-range damage"], ["Hurts itself each burst", "Fragile at range"],
          ["Rib Burst: spikes erupt and poison nearby foes", "Venom Coat: poison a weapon", "Skewer: a heavy rib-thrust"],
          "Rib-spike harness, venom vials, bone knife, leather wraps",
          "Dark, spotted ribbed newt-kin crouched low with rows of pale orange rib-spikes bursting from its sides, a vial in one hand.", ["#3d3a2a", "#e0902a", "#a8e063"]),
        L("riverskinguardians", "Hellbender Riverskin Guardians", "waves", "combat", "Cold water. Clean skin.",
          "Wrinkled hellbenders who breathe through their folded skin in cold fast rivers. Riverskin Guardians hold a current like a wall and never tire in clean water.",
          "North America's biggest salamander has no use for gills or much for lungs. It needs only clean water, and it will defend any river that has it.",
          ["Never tires in running water", "Strong defense in rivers and rain"], ["Weak in dirty or still water", "Slow on land"],
          ["Skin Fold: gain armor from flowing water", "Current Hold: root enemies in a stream", "Clean Water: purify an area"],
          "Folded-skin cloak, river-stone shield, current-staff, flat gripping gloves",
          "Wide, wrinkled hellbender-kin in a ridged skin-cloak planting a river-stone shield, water streaming off its folds.", ["#4a5f6a", "#f2c14e", "#b5e48c"]),
      ]),
    /* 6 ------------------------------------------------ AVIAN */
    M("avian", "Avian-kin", "bird", "They saw it coming.",
      "Three birds, three trades: the ravens (flock-fighters with long memories), the owls (silent night marksmen) and the albatross (long-range scouts who carry the wind). Winged, watchful and very hard to surprise.",
      "They run the sky-post, patrol the borders at night and cross the territory without ever being stopped. They have read everyone's mail, and they remember what you said to them last winter.",
      [
        L("murdervanguard", "Raven Murder Vanguard", "bird", "combat", "One of us. All of us.",
          "Flock-fighters who attack as a swarm. Murder Vanguard raiders dive in formation, striking from every side at once.",
          "They remember every grudge, including grudges inherited from their grandparents. The flock keeps the list.",
          ["Coordinated flock strikes", "Strong against single targets"], ["Weak when isolated", "Hold grudges too long"],
          ["Flock Dive: allies and shadow-crows strike together", "Memory Mark: tag a foe who wronged the flock", "Scatter: split into crows and reform elsewhere"],
          "Talon-blades, feather mantle, black-iron beak mask, grudge ledger",
          "Raven-kin in a black beak mask diving with talon-blades, a swarm of crows streaming behind.", ["#282956", "#ef233c", "#def6ff"]),
        L("nighteyesnipers", "Owl Night-Eye Snipers", "crosshair", "combat", "Enormous eyes. One bullet.",
          "Marksmen who see everything in the dark. Night-Eye Snipers perch on dead pylons and pick off targets from a mile away.",
          "Their eyes are the size of dinner plates, and they have never once missed in the dark.",
          ["Extreme range and night vision", "Reveal the enemy's position for allies"], ["Poor in daylight", "Slow to relocate"],
          ["Dead-Eye Shot: ranged critical", "Night Scope: see through fog and cover", "Perch: gain height and range"],
          "Long rifle with thermal scope, night-goggles, ghillie cloak",
          "Owl-kin on a rusted pylon with a long rifle and thermal scope, huge golden eyes glowing in the dark.", ["#fff5bc", "#3c096c", "#c6e2fe"]),
        L("galesailors", "Albatross Gale Sailors", "bird", "support", "Wind at your back. Always.",
          "Albatross navigators who ride the long winds and share them. Gale Sailors scout the whole territory from the sky and fill their allies' sails with a tailwind.",
          "An albatross can cross an ocean without landing, and the Pack's Gale Sailors have crossed every border without being stopped. They carry the weather in their wings.",
          ["Long-range scouting and map reveal", "Speed and range buffs for the whole party"], ["Clumsy on the ground", "Low damage"],
          ["Tailwind: boost an ally's speed for a turn", "Long Glide: scout a far zone and reveal it", "Storm Petrel Call: summon a gust that pushes enemies back"],
          "Sea-chart satchel, weather vane staff, wind-flag banner, goggles",
          "Huge-winged albatross-kin in a salt-stained coat holding a weather-vane staff, wings wide and a flag snapping in the wind behind.", ["#2a74b8", "#f4f1e8", "#ffb347"]),
      ]),
    /* 8 ------------------------------------------------ OCTOPUS */
    M("cephalopod", "Cephalopod-kin", "octopus", "Many arms. No plans you've seen.",
      "Three kinds of cephalopod, three trades: the octopus scholars (ink magic and extraordinary intelligence), the cuttlefish spies (living camouflage) and the squid engineers (fast, many-armed builders). A radical departure from humanoid anatomy.",
      "They live in sunken subway tunnels and flooded data-vaults. Every cephalopod keeps a hundred secrets and does not trust the other ninety-nine.",
      [
        L("inkspies", "Cuttlefish Ink Spies", "pen-tool", "combat", "You'll never see them.",
          "Cuttlefish infiltrators who blend into walls and disappear in a cloud of ink. Ink Spies slip through any guard and strike from the dark.",
          "A cuttlefish's skin changes color to match any surface, and so do their stories. They read the room before they enter it.",
          ["Superb camouflage and infiltration", "Strong burst from stealth"], ["Fragile", "Low sustained damage"],
          ["Ink Cloud: vanish and blind enemies", "Chameleon Skin: blend into any surface", "Constrict: grab and drag an enemy"],
          "Ink-bomb pouch, suction-grip gloves, silenced pistol, camo cloak",
          "Cuttlefish-kin with a wide fin skirt and W-shaped pupils dissolving into a wall, arms wrapped around a silenced pistol, a cloud of ink spilling.", ["#9518a2", "#06d6a0", "#002645"]),
        L("tentacleengineers", "Squid Tentacle Engineers", "cog", "combat", "Eight hands. Eight tools.",
          "Squid combat engineers who build and wield tools in all ten limbs at once. Tentacle Engineers work a battlefield like a workshop: a turret here, a barricade there, a bomb behind you.",
          "A squid has eight arms and two long grabbing tentacles, and no one else can hold a wrench, a welder, a rifle and a screwdriver simultaneously.",
          ["Build turrets and barricades quickly", "Strong multitasking in combat"], ["Gadgets overheat", "Fragile body"],
          ["Eight-Arm Build: place several structures at once", "Welding Arc: burn a target", "Overload: detonate a nearby structure"],
          "Multi-tool harness, welder, scrap turret, goggles",
          "Squid-kin with a torpedo-shaped mantle and a tool in each limb, building a turret while a welder sparks overhead.", ["#fda96c", "#00b4d8", "#282956"]),
        L("abyssalscholars", "Octopus Abyssal Scholars", "notebook", "combat", "Knowledge is deep. So are we.",
          "Occult casters who bring ancient sunken knowledge to the surface. Abyssal Scholars cast from tomes, tentacles and a lot of ink.",
          "They read from books that are still wet, and some of the books read back.",
          ["Strong control and damage spells", "Learn rare abilities from tomes"], ["Slow casting", "Dependent on books"],
          ["Tome Burst: unleash an ink-spell", "Deep Whisper: confuse an enemy's mind", "Void Grip: hold a target with spectral tentacles"],
          "Sodden tome, ink wand, goggles, scroll case",
          "Octopus-kin in a tall pointed hood and goggles reading from an open tome while ink swirls from a wand and tentacles coil around them.", ["#270077", "#e0aaff", "#1c2337"]),
      ]),
    /* 9 ------------------------------------------------ CRUSTACEA-KIN */
    M("crustacea", "Crustacea-kin", "shrimp", "The punch that breaks the sound barrier.",
      "Seven armored crustaceans, seven ways to win: the mantis shrimp (the fastest punch), the lobster (a Malacostracan tank), the pistol shrimp (a sonic snap), the yeti crab (a farm on its claws), the boxer crab (anemone gloves), the remipede (cave venom) and the pram bug (a living nursery).",
      "They live in reef-forts, flooded stadiums, hydrothermal vents and blind caves. A crustacean does not talk before a fight. The shell does.",
      [
        L("punchclawduelists", "Mantis Shrimp Punch-Claw Duelists", "sword", "combat", "One strike. Done.",
          "Duelists with explosive club-claws. Punch-Claw Duelists win a fight with the very first strike, and so far none have lost.",
          "Their clubs move faster than a bullet, and the shockwave breaks bone and glass alike.",
          ["Highest single-hit damage among Kin", "Break armor and shields"], ["Slow recovery after a strike", "Fragile shell if cracked"],
          ["Shockwave Strike: burst damage that cracks armor", "Cavitation Pop: stun everyone nearby", "Quick Recoil: reset the strike"],
          "Club-claws, plated carapace, striking gauntlets, reef-cloak",
          "Armored mantis-shrimp-kin mid-punch with a glowing club-claw, a shockwave rippling the water.", ["#ca148b", "#ffd60a", "#023e8a"]),
        L("lobsterclawmarshals", "Lobster Claw-Marshals", "shield", "combat", "Crush first. Parley later.",
          "Armored Malacostracan marshals in lobster shells. Claw-Marshals hold the line with a crusher claw and a cutter claw.",
          "A lobster is a living fortress with a taste for order. They keep the reef-forts' laws and enforce them with one big claw.",
          ["Huge armor and crushing grip", "Pins enemies in place"], ["Slow turning", "Weak when flipped or cracked"],
          ["Crusher Claw: a heavy grip that holds a target", "Cutter Claw: a quick slashing strike", "Molt: shed a broken shell for fresh armor"],
          "Crusher claw gauntlet, cutter claw, plated carapace, marshal's sash",
          "Huge armored lobster-kin with a big crusher claw and a smaller cutter claw raised, long antennae and a tail fan.", ["#e72364", "#f4f1e8", "#ff5d8f"]),
        L("pistolshrimpsnapgunners", "Pistol Shrimp Snap-Gunners", "crosshair", "combat", "One claw. One crack.",
          "Tiny shrimp with an oversized claw that snaps shut with a sonic crack. Snap-Gunners fire a cavitation bubble that stuns everything ahead.",
          "The snap is louder than a gunshot and briefly as hot as the sun. A Snap-Gunner never hears it. They wear earplugs.",
          ["Burst stun and sonic damage", "Strong against shields and armor"], ["Tiny and fragile", "Needs a moment to reset the claw"],
          ["Snap: a shockwave that stuns everything ahead", "Cavitation Bubble: a hot bubble that bursts for area damage", "Ear Plugs: ignore stuns and silence"],
          "Oversized snap-claw gauntlet, earplug headset, bubble flask, shell vest",
          "Small wiry pistol-shrimp-kin with one huge oversized claw cocked like a hammer, a pale bubble blooming from its tip.", ["#f4bb2a", "#1f2438", "#ff8a3d"]),
        L("yetisetaefarmers", "Yeti Crab Setae Farmers", "flower", "support", "Fur makes food.",
          "Pale yeti-crabs who farm bacteria on the thick hair of their claws. Setae Farmers feed and heal allies with their living harvest.",
          "Deep in the vent-fields the yeti crabs wave their furry claws over the warm water and the bacteria bloom. A Farmer shares every harvest.",
          ["Heals and buffs with a living harvest", "Rebuilds the party between fights"], ["Low damage", "Glows white in the dark"],
          ["Bloom: a bacteria patch that heals over time", "Hairy Claw Wave: cleanse and nourish nearby allies", "Warm Vent: a zone that boosts regeneration"],
          "Furry setae claws, farming jars, vent lamp, carrying basket",
          "Stark-white yeti-crab-kin waving two thick hair-covered claws, jars of glowing bacteria at the belt.", ["#bee4ef", "#e8c76a", "#06d6a0"]),
        L("boxercrabanemonebrawlers", "Boxer Crab Anemone Brawlers", "heart", "combat", "Left hook. Right hook. Sting.",
          "Tiny boxer crabs who fight with a live venomous anemone in each claw. Anemone Brawlers jab, sting and split a glove when one is lost.",
          "A boxer crab is the smallest champion in the reef. If a glove is lost, they tear the other in half, and it grows back.",
          ["Fast poisonous combos", "Regrows its gloves by splitting them"], ["Tiny and light", "Gloves are fragile"],
          ["One-Two: a double jab that poisons", "Split Glove: tear a glove in two to refresh the combo", "Sting Block: guard and poison anyone who strikes"],
          "Anemone gloves, boxing trunks, champion belt, mouth guard",
          "Small boxer-crab-kin in a fighting stance with a venomous pink anemone on each claw like a boxing glove.", ["#db57a6", "#2d2a4a", "#4cc9f0"]),
        L("remipedecavestalkers", "Remipede Cave-Venom Stalkers", "bone", "combat", "Blind. Fanged. Quiet.",
          "Blind remipede-kin who prowl flooded caves and inject neurotoxin through hollow fangs. Cave-Venom Stalkers strike unseen and liquefy their prey.",
          "They have no eyes and never needed them. A Stalker feels every drop of water in the cave and knows exactly where you stand.",
          ["Deadly venom and blind-fighting", "Excels in darkness and water"], ["Weak in bright light", "Fragile body"],
          ["Venom Fang: a neurotoxin strike that weakens", "Many Legs: climb and swim without a sound", "Liquefy: heavy damage over time on a poisoned target"],
          "Venom fangs, cave-stick, many-legged harness, vial belt",
          "Pale, eyeless remipede-kin with a long segmented body and hollow fangs, many legs trailing and venom dripping.", ["#3f1f7a", "#fff7e0", "#c77dff"]),
        L("prambugnurserypilots", "Pram Bug Nursery Pilots", "egg", "support", "Home is where you push it.",
          "Translucent pram bugs who hollow out a salp and push it along as a drifting nursery. Nursery Pilots shelter allies inside the barrel, heal them and ferry them across water.",
          "A pram bug carves a barrel from a gelatinous salp, lays her eggs inside and drifts the open ocean pushing it ahead. It is the strangest ambulance in the world.",
          ["Shelters and heals allies in a barrel", "Carries the party across water"], ["Fragile", "Slow while pushing the barrel"],
          ["Barrel Home: shelter allies in a protective barrel", "Nursery Glow: heal everyone inside over time", "Drift: ferry the party across open water"],
          "Salp-barrel shell, translucent claws, pushing pole, egg satchel",
          "Translucent long-limbed pram-bug-kin with big eyes pushing a hollow barrel-shaped salp shell like a pram, tiny eggs glowing inside.", ["#94cdd1", "#26324a", "#ffd23f"]),
      ]),
    /* 10 ------------------------------------------------ MOTH */
    M("moth", "Moth-kin", "moth", "Drawn to the old lights.",
      "Huge patterned wings, feathery antennae, nocturnal behavior and an attraction to ancient lights. Perfect for lantern cults, dream magic and forgotten signal towers.",
      "They gather around dead beacons and flicker in the dark. A Moth who finds a working light will follow it anywhere, including into a fight.",
      [
        L("lanterncultists", "Lantern Cultists", "lantern", "combat", "Follow the light. Burn for it.",
          "Zealots who worship dead lights and fight with fire and flares. Lantern Cultists are drawn to the biggest light on the field and make it theirs.",
          "Their wings are patterned like eyes, and every flare they raise is a prayer.",
          ["Strong fire and light damage", "Draw enemy attention away from allies"], ["Blind to anything but the brightest light", "Fragile"],
          ["Flare Burst: blinding area damage", "Beacon Call: draw enemies to a light", "Wingbeat Gust: scatter embers and push enemies back"],
          "Flare launcher, lantern staff, ash-dusted robes, signal mirror",
          "Moth-kin with huge eye-patterned wings holding a blazing lantern staff, embers swirling around them.", ["#d7ce04", "#cc0b38", "#410f1f"]),
        L("dreamdustweavers", "Dreamdust Weavers", "sparkles", "support", "Sleep well. Fight better.",
          "Dream-magic supporters who shower allies with glowing dust. Dreamdust Weavers soothe, strengthen and put enemies to sleep.",
          "Their wings leave a trail of shimmering scales. Anyone who breathes it sees something wonderful, then something worse.",
          ["Powerful party buffs and sleep effects", "Calm and cleanse minds"], ["Almost no direct damage", "Fragile wings"],
          ["Dreamdust: heal and buff an area", "Lull: put an enemy to sleep", "Nightmare Mirror: reflect an enemy's fear back"],
          "Dust-satchel, feather duster staff, scale-powder pots, shawl",
          "Moth-kin with shimmering dusty wings sprinkling glowing dust over allies, eyes half-closed in a dream.", ["#b668f9", "#ffc8dd", "#2e0d52"]),
        L("signaltowerwardens", "Signal-Tower Wardens", "antenna", "combat", "Keep the old signal alive.",
          "Guardians of forgotten radio towers. Signal-Tower Wardens fight from towers and ruins, casting with radio static and light.",
          "They climb dead towers to tend relics nobody remembers. Sometimes the towers answer.",
          ["Strong ranged static and light attacks", "Reveal hidden enemies with signal sweeps"], ["Tied to towers", "Weak in the open"],
          ["Static Burst: ranged electric blast", "Sweep Signal: reveal and mark enemies", "Dead Air: silence enemy casters"],
          "Signal rod, radio headset, antenna pack, climbing harness",
          "Moth-kin atop a rusted radio tower, antennae twitching, a signal rod crackling with static.", ["#30a8f5", "#f72585", "#4a4e69"]),
      ]),
    /* 11 ------------------------------------------------ PANGOLIN */
    M("pangolin", "Pangolin-kin", "pangolin", "Armor you can curl up in.",
      "Overlapping armor plates, enormous digging claws and defensive curling. A fascinating alternative to standard armored warriors, with an instantly readable silhouette.",
      "They dig the tunnels under the ruins and hold the bunkers nobody else can crack. When a Pangolin curls up, the battle waits.",
      [
        L("platewallbulwarks", "Plate-Wall Bulwarks", "shield", "combat", "Layered. Impenetrable.",
          "Frontline tanks in overlapping plate. Plate-Wall Bulwarks lock together into a rolling wall and soak damage no one else can.",
          "Each plate is salvaged from a different machine, hammered into place and numbered. A Bulwark knows its own plates by name.",
          ["Top-tier armor and defense", "Lock plates with allies for a shared wall"], ["Slow", "Low damage on their own"],
          ["Plate Lock: join a shield wall with allies", "Curl Up: take no damage for one turn", "Scale Burst: launch plate shards at nearby enemies"],
          "Layered plate armor, tower shield, hand-forged mace, shoulder plates",
          "Pangolin-kin in layered salvage-plate armor behind a huge shield, scales gleaming under rain.", ["#febab2", "#4a4e69", "#fdce53"]),
        L("tunneldiggers", "Tunnel Diggers", "pickaxe", "combat", "Under you. Around you.",
          "Siege miners with huge digging claws. Tunnel Diggers open flanks, collapse walls and pop up exactly where the enemy isn't looking.",
          "They have dug under every fortress in the Dim, and none of the fortresses have noticed yet.",
          ["Tunnel across the battlefield", "Strong against fortifications"], ["Slow on the surface", "Vulnerable when surfacing"],
          ["Burrow: vanish underground and reappear", "Claw Rend: heavy melee damage", "Collapse: bring down a wall or ceiling"],
          "Digging claws, mining helmet, shaft-lamp, dynamite belt",
          "Pangolin-kin bursting from the ground with huge digging claws, dirt and plates flying.", ["#663502", "#f4a261", "#264653"]),
        L("curlballrollers", "Curl-Ball Rollers", "bolt", "combat", "Roll out.",
          "Curl into a ball and charge through the enemy line. Curl-Ball Rollers are living cannonballs with the armor to survive it.",
          "A Roller will curl up and go down a hill, through three barricades and a bad plan, and win.",
          ["Devastating charge damage", "Immune to most damage while curled"], ["Cannot steer well", "Vulnerable when uncurled"],
          ["Cannonball: roll through a line of enemies", "Curl Up: gain full defense", "Uncurl Strike: stun nearby foes when ending a roll"],
          "Spiked plates, rolling harness, charge helm, goggles",
          "Pangolin-kin mid-roll as an armored ball, sparks flying off the plates, enemies scattering.", ["#e5f102", "#fd4d50", "#3a0ca3"]),
      ]),
    /* 12 ------------------------------------------------ SPIDER */
    M("spider", "Spider-kin", "spider", "Everything is a web.",
      "Multiple eyes, silk production, unusual limb arrangements and vertical movement. Slim, many-limbed Kin who fight with cable, wire and silk.",
      "They run the cable-roads between the keeps and sit at the center of every message the Dim has ever sent.",
      [
        L("loomweavers", "Loomweavers", "yarn", "combat", "The trap is already built.",
          "Trap-setters who rig the battlefield with razor wire. Loomweavers win a fight before it starts.",
          "Their snares are woven from salvaged copper and silk. They are strong as steel and light as lace.",
          ["Excellent trapping and area control", "Strong setups for allies"], ["Slow to set up", "Burn easily"],
          ["Snare Line: trap enemies", "Wire Bridge: cross gaps", "Razor Web: area damage over time"],
          "Spool of razor-wire, spinneret gauntlet, silk shawl, hook knives",
          "Many-limbed figure in a silk-and-wire coat, threads of cable fanning across the frame.", ["#e0aaff", "#06d6a0", "#201c49"]),
        L("silkroad", "Silkroad Messengers", "mail", "support", "The message arrives first.",
          "Communicators who send messages along cable-lines faster than any bird. Silkroad Messengers coordinate the party, mark targets and call for help.",
          "They feel a vibration on a thread miles away. They know most news first and never gossip, much.",
          ["Instant long-distance coordination", "Mark targets for the party"], ["Fragile", "Network can be cut"],
          ["Thread Whisper: send a message anywhere", "Feel the Strand: sense nearby creatures", "Express Line: fast travel for allies"],
          "Courier bag, signal spool, hand-crank radio, tiny cap",
          "Upside-down spider-kin hanging from a cable, a letter in one limb and a radio at the hip.", ["#dc8495", "#4ecdc4", "#fff3b0"]),
        L("dewdrop", "Dewdrop Dancers", "bolt", "combat", "Tiny. Quick. Everywhere.",
          "Jumping-spider assassins who strike in acrobatic bursts. Dewdrop Dancers dodge everything, hit hard and are gone.",
          "They are the smallest of the Kin and the deadliest per ounce. They perform in the treetops for fun and for war.",
          ["Extreme mobility and dodge", "Strong burst damage"], ["Small and fragile", "Short range"],
          ["Leap: jump to any target", "Twirl: dodge attacks", "Pirouette Strike: spin attack"],
          "Twin hooked blades, jump-boots, dewdrop buckler, tiny cape",
          "Tiny spider-kin mid-leap with twin blades flashing, a trail of glittering droplets behind.", ["#fe73e6", "#90e0ef", "#fff1e6"]),
      ]),
  ],
};
